window.CHUJI_DATA_15 = [{"l": 441, "lt": "Lesson 141 Global Warming 全球气温上升", "i": 1, "type": "reading", "en": "Have you noticed that it's getting warmer and warmer every year?", "zh": "你有没有注意到天气一年比一年变得还要暖和了呢？", "audio": "chuji_l141_01.mp3", "localAudio": "audio_chunks/chuji_l141_01.mp3", "b64": "", "src": "chuji"}, {"l": 441, "lt": "Lesson 141 Global Warming 全球气温上升", "i": 2, "type": "reading", "en": "To put it simply, that's because of air pollution.", "zh": "简言之，那是因为空气污染的缘故。", "audio": "chuji_l141_02.mp3", "localAudio": "audio_chunks/chuji_l141_02.mp3", "b64": "", "src": "chuji"}, {"l": 441, "lt": "Lesson 141 Global Warming 全球气温上升", "i": 3, "type": "reading", "en": "Scientists tell us that because of air pollution, the earth's heat cannot escape.", "zh": "科学家告诉我们由于空气污染，地球的热气无法散出去。", "audio": "chuji_l141_03.mp3", "localAudio": "audio_chunks/chuji_l141_03.mp3", "b64": "", "src": "chuji"}, {"l": 441, "lt": "Lesson 141 Global Warming 全球气温上升", "i": 4, "type": "reading", "en": "This is known as global warming.", "zh": "这就是为人所知的全球变暖。", "audio": "chuji_l141_04.mp3", "localAudio": "audio_chunks/chuji_l141_04.mp3", "b64": "", "src": "chuji"}, {"l": 441, "lt": "Lesson 141 Global Warming 全球气温上升", "i": 5, "type": "reading", "en": "If this situation is allowed to continue, it will just keep getting hotter and hotter.", "zh": "如果我们任由这种情形一直持续下去，地球就会变得越来越热。", "audio": "chuji_l141_05.mp3", "localAudio": "audio_chunks/chuji_l141_05.mp3", "b64": "", "src": "chuji"}, {"l": 441, "lt": "Lesson 141 Global Warming 全球气温上升", "i": 6, "type": "reading", "en": "Then, can you imagine what will happen?", "zh": "那么，你能想象会发生什么事吗？", "audio": "chuji_l141_06.mp3", "localAudio": "audio_chunks/chuji_l141_06.mp3", "b64": "", "src": "chuji"}, {"l": 441, "lt": "Lesson 141 Global Warming 全球气温上升", "i": 7, "type": "reading", "en": "We should all, therefore, do our part to stop polluting the air and help save the world.", "zh": "因此，我们全都应该尽一己之力来防止污染空气并拯救地球。", "audio": "chuji_l141_07.mp3", "localAudio": "audio_chunks/chuji_l141_07.mp3", "b64": "", "src": "chuji"}, {"l": 442, "lt": "Lesson 142 No Smoking 禁止吸烟", "i": 1, "type": "dialog", "en": "Can I have an ashtray, please?", "zh": "请给我一个烟灰缸好吗？", "audio": "chuji_l142_01.mp3", "localAudio": "audio_chunks/chuji_l142_01.mp3", "b64": "", "src": "chuji", "speaker": "Customer", "note": "说话人: Customer"}, {"l": 442, "lt": "Lesson 142 No Smoking 禁止吸烟", "i": 2, "type": "dialog", "en": "I'm sorry, sir. This is a non-smoking section.", "zh": "很抱歉，先生。这里是非吸烟区。", "audio": "chuji_l142_02.mp3", "localAudio": "audio_chunks/chuji_l142_02.mp3", "b64": "", "src": "chuji", "speaker": "Waiter", "note": "说话人: Waiter"}, {"l": 442, "lt": "Lesson 142 No Smoking 禁止吸烟", "i": 3, "type": "dialog", "en": "Where's the smoking section?", "zh": "吸烟区在哪里？", "audio": "chuji_l142_03.mp3", "localAudio": "audio_chunks/chuji_l142_03.mp3", "b64": "", "src": "chuji", "speaker": "Customer", "note": "说话人: Customer"}, {"l": 442, "lt": "Lesson 142 No Smoking 禁止吸烟", "i": 4, "type": "dialog", "en": "Over there.", "zh": "在那里。", "audio": "chuji_l142_04.mp3", "localAudio": "audio_chunks/chuji_l142_04.mp3", "b64": "", "src": "chuji", "speaker": "Waiter", "note": "说话人: Waiter"}, {"l": 443, "lt": "Lesson 143 Man's Best Friend 人类最好的朋友", "i": 1, "type": "reading", "en": "The dog is man's best friend.", "zh": "狗是人类最好的朋友。", "audio": "chuji_l143_01.mp3", "localAudio": "audio_chunks/chuji_l143_01.mp3", "b64": "", "src": "chuji"}, {"l": 443, "lt": "Lesson 143 Man's Best Friend 人类最好的朋友", "i": 2, "type": "reading", "en": "He can do many things for us.", "zh": "它可以为我们做许多事情。", "audio": "chuji_l143_02.mp3", "localAudio": "audio_chunks/chuji_l143_02.mp3", "b64": "", "src": "chuji"}, {"l": 443, "lt": "Lesson 143 Man's Best Friend 人类最好的朋友", "i": 3, "type": "reading", "en": "He can protect our homes.", "zh": "它可以保护我们的家。", "audio": "chuji_l143_03.mp3", "localAudio": "audio_chunks/chuji_l143_03.mp3", "b64": "", "src": "chuji"}, {"l": 443, "lt": "Lesson 143 Man's Best Friend 人类最好的朋友", "i": 4, "type": "reading", "en": "He can guide the blind.", "zh": "它可以引导盲人。", "audio": "chuji_l143_04.mp3", "localAudio": "audio_chunks/chuji_l143_04.mp3", "b64": "", "src": "chuji"}, {"l": 443, "lt": "Lesson 143 Man's Best Friend 人类最好的朋友", "i": 5, "type": "reading", "en": "He is loyal to his master and never asks for a pay raise.", "zh": "它对主人忠实而且从不要求加薪。", "audio": "chuji_l143_05.mp3", "localAudio": "audio_chunks/chuji_l143_05.mp3", "b64": "", "src": "chuji"}, {"l": 443, "lt": "Lesson 143 Man's Best Friend 人类最好的朋友", "i": 6, "type": "reading", "en": "The dog has also made many contributions to English.", "zh": "狗还对英文有许多的贡献。", "audio": "chuji_l143_06.mp3", "localAudio": "audio_chunks/chuji_l143_06.mp3", "b64": "", "src": "chuji"}, {"l": 443, "lt": "Lesson 143 Man's Best Friend 人类最好的朋友", "i": 7, "type": "reading", "en": "For example, if there were no dogs, how could a husband tell his wife her cooking tastes like dog food?", "zh": "举例来说，如果没有狗的话，做丈夫的如何告诉他太太她煮的菜吃起来像狗食？", "audio": "chuji_l143_07.mp3", "localAudio": "audio_chunks/chuji_l143_07.mp3", "b64": "", "src": "chuji"}, {"l": 443, "lt": "Lesson 143 Man's Best Friend 人类最好的朋友", "i": 8, "type": "reading", "en": "How could the weatherman say, \"It's raining cats and dogs?\" So the next time a dog lifts a leg to your bicycle, don't kick him.", "zh": "气象播报员又如何能用猫和狗来表示雨下得很大呢？", "audio": "chuji_l143_08.mp3", "localAudio": "audio_chunks/chuji_l143_08.mp3", "b64": "", "src": "chuji"}, {"l": 443, "lt": "Lesson 143 Man's Best Friend 人类最好的朋友", "i": 9, "type": "reading", "en": "Bend down and say,\"Take your time.\"", "zh": "因此下次有狗对你的自行车", "audio": "chuji_l143_09.mp3", "localAudio": "audio_chunks/chuji_l143_09.mp3", "b64": "", "src": "chuji"}, {"l": 444, "lt": "Lesson 144 The Year of the Dog 狗年", "i": 1, "type": "dialog", "en": "When were you born?", "zh": "你何时出生的？", "audio": "chuji_l144_01.mp3", "localAudio": "audio_chunks/chuji_l144_01.mp3", "b64": "", "src": "chuji", "speaker": "Tracy", "note": "说话人: Tracy"}, {"l": 444, "lt": "Lesson 144 The Year of the Dog 狗年", "i": 2, "type": "dialog", "en": "In the Year of the Dog.", "zh": "狗年出生的。", "audio": "chuji_l144_02.mp3", "localAudio": "audio_chunks/chuji_l144_02.mp3", "b64": "", "src": "chuji", "speaker": "Ivan", "note": "说话人: Ivan"}, {"l": 444, "lt": "Lesson 144 The Year of the Dog 狗年", "i": 3, "type": "dialog", "en": "What does that mean?", "zh": "那是什么意思？", "audio": "chuji_l144_03.mp3", "localAudio": "audio_chunks/chuji_l144_03.mp3", "b64": "", "src": "chuji", "speaker": "Tracy", "note": "说话人: Tracy"}, {"l": 444, "lt": "Lesson 144 The Year of the Dog 狗年", "i": 4, "type": "dialog", "en": "Oh. That's one of the twelve Chinese horoscope animals. I was born in 1970.", "zh": "哦。那是中国的十二生肖之-。我出生于1970年。", "audio": "chuji_l144_04.mp3", "localAudio": "audio_chunks/chuji_l144_04.mp3", "b64": "", "src": "chuji", "speaker": "Ivan", "note": "说话人: Ivan"}, {"l": 444, "lt": "Lesson 144 The Year of the Dog 狗年", "i": 5, "type": "dialog", "en": "That's interesting. I was born in 1971. What animal am I?", "zh": "真有趣。我出生于197]年。我属于什么生肖？", "audio": "chuji_l144_05.mp3", "localAudio": "audio_chunks/chuji_l144_05.mp3", "b64": "", "src": "chuji", "speaker": "Tracy", "note": "说话人: Tracy"}, {"l": 444, "lt": "Lesson 144 The Year of the Dog 狗年", "i": 6, "type": "dialog", "en": "You're a pig!", "zh": "你属猪！", "audio": "chuji_l144_06.mp3", "localAudio": "audio_chunks/chuji_l144_06.mp3", "b64": "", "src": "chuji", "speaker": "Ivan", "note": "说话人: Ivan"}, {"l": 445, "lt": "Lesson 145 Billy's Goal in Life 比利的人生目标", "i": 1, "type": "reading", "en": "Some people have goals in life.", "zh": "有些人的人生有目标。", "audio": "chuji_l145_01.mp3", "localAudio": "audio_chunks/chuji_l145_01.mp3", "b64": "", "src": "chuji"}, {"l": 445, "lt": "Lesson 145 Billy's Goal in Life 比利的人生目标", "i": 2, "type": "reading", "en": "For these people it is important to achieve their goals.", "zh": "对这些人来说，达到他们的目标是很重要的。", "audio": "chuji_l145_02.mp3", "localAudio": "audio_chunks/chuji_l145_02.mp3", "b64": "", "src": "chuji"}, {"l": 445, "lt": "Lesson 145 Billy's Goal in Life 比利的人生目标", "i": 3, "type": "reading", "en": "As for my brother Billy, his goal in life is to make people happy.", "zh": "至于我哥哥比利，他人生的目标是让别人快乐。", "audio": "chuji_l145_03.mp3", "localAudio": "audio_chunks/chuji_l145_03.mp3", "b64": "", "src": "chuji"}, {"l": 445, "lt": "Lesson 145 Billy's Goal in Life 比利的人生目标", "i": 4, "type": "reading", "en": "He tries to accomplish this by being a good student and an obedient son.", "zh": "他设法以做一名好学生和乖儿子来完成这个目标。", "audio": "chuji_l145_04.mp3", "localAudio": "audio_chunks/chuji_l145_04.mp3", "b64": "", "src": "chuji"}, {"l": 445, "lt": "Lesson 145 Billy's Goal in Life 比利的人生目标", "i": 5, "type": "reading", "en": "In this way, he is able to give joy to those who are dearest to him ----- his teachers and his family.", "zh": "这样一来，他就能将快乐给予跟他最亲的人一也就是他的老师和家人。", "audio": "chuji_l145_05.mp3", "localAudio": "audio_chunks/chuji_l145_05.mp3", "b64": "", "src": "chuji"}, {"l": 445, "lt": "Lesson 145 Billy's Goal in Life 比利的人生目标", "i": 6, "type": "reading", "en": "It's too bad we don't all have goals like Billy.", "zh": "令人遗憾的是，并不是所有的人都像比利一样有人生目标。", "audio": "chuji_l145_06.mp3", "localAudio": "audio_chunks/chuji_l145_06.mp3", "b64": "", "src": "chuji"}, {"l": 446, "lt": "Lesson 146 Being Happy 快乐", "i": 1, "type": "dialog", "en": "What's your goal in life, Kathy?", "zh": "凯茜，你的人生目标是什么？", "audio": "chuji_l146_01.mp3", "localAudio": "audio_chunks/chuji_l146_01.mp3", "b64": "", "src": "chuji", "speaker": "Bill", "note": "说话人: Bill"}, {"l": 446, "lt": "Lesson 146 Being Happy 快乐", "i": 2, "type": "dialog", "en": "My goal is to be rich. What about you?", "zh": "我的目标就是要有钱。你的目标呢？", "audio": "chuji_l146_02.mp3", "localAudio": "audio_chunks/chuji_l146_02.mp3", "b64": "", "src": "chuji", "speaker": "Kathy", "note": "说话人: Kathy"}, {"l": 446, "lt": "Lesson 146 Being Happy 快乐", "i": 3, "type": "dialog", "en": "I just want to be happy.", "zh": "我只想要快乐。", "audio": "chuji_l146_03.mp3", "localAudio": "audio_chunks/chuji_l146_03.mp3", "b64": "", "src": "chuji", "speaker": "Bill", "note": "说话人: Bill"}, {"l": 446, "lt": "Lesson 146 Being Happy 快乐", "i": 4, "type": "dialog", "en": "What?", "zh": "什么？", "audio": "chuji_l146_04.mp3", "localAudio": "audio_chunks/chuji_l146_04.mp3", "b64": "", "src": "chuji", "speaker": "Kathy", "note": "说话人: Kathy"}, {"l": 446, "lt": "Lesson 146 Being Happy 快乐", "i": 5, "type": "dialog", "en": "I think being happy is more important than having all the money in the world.", "zh": "我认为快乐要比拥有世上所有的钱来得重要。", "audio": "chuji_l146_05.mp3", "localAudio": "audio_chunks/chuji_l146_05.mp3", "b64": "", "src": "chuji", "speaker": "Bill", "note": "说话人: Bill"}, {"l": 447, "lt": "Lesson 147 Television Addiction 电视迷", "i": 1, "type": "reading", "en": "Television provides us with a wide range of information and entertainment.", "zh": "电视给我们提供广泛的信息和娱乐。", "audio": "chuji_l147_01.mp3", "localAudio": "audio_chunks/chuji_l147_01.mp3", "b64": "", "src": "chuji"}, {"l": 447, "lt": "Lesson 147 Television Addiction 电视迷", "i": 2, "type": "reading", "en": "However, it's a pity that it may also have a bad influence on young minds.", "zh": "不过，遗憾的是，它也会对年轻人的思想有不良的影响。", "audio": "chuji_l147_02.mp3", "localAudio": "audio_chunks/chuji_l147_02.mp3", "b64": "", "src": "chuji"}, {"l": 447, "lt": "Lesson 147 Television Addiction 电视迷", "i": 3, "type": "reading", "en": "For instance, some TV shows have too much violence and crime.", "zh": "举例来说，有些电视节目有太多的暴力和犯罪。", "audio": "chuji_l147_03.mp3", "localAudio": "audio_chunks/chuji_l147_03.mp3", "b64": "", "src": "chuji"}, {"l": 447, "lt": "Lesson 147 Television Addiction 电视迷", "i": 4, "type": "reading", "en": "These programs may lead youngsters astray.", "zh": "这样的节目可能使年轻人误入歧途。", "audio": "chuji_l147_04.mp3", "localAudio": "audio_chunks/chuji_l147_04.mp3", "b64": "", "src": "chuji"}, {"l": 447, "lt": "Lesson 147 Television Addiction 电视迷", "i": 5, "type": "reading", "en": "It is easy for students to become addicted to the excitement of these programs and neglect their homework.", "zh": "学生很容易沉溺于这些刺激的节目中而忽视了他们的功课。", "audio": "chuji_l147_05.mp3", "localAudio": "audio_chunks/chuji_l147_05.mp3", "b64": "", "src": "chuji"}, {"l": 447, "lt": "Lesson 147 Television Addiction 电视迷", "i": 6, "type": "reading", "en": "Parents must, therefore, keep an eye on what their children watch.", "zh": "因此，父母们应该留意孩子所看的电视节目。", "audio": "chuji_l147_06.mp3", "localAudio": "audio_chunks/chuji_l147_06.mp3", "b64": "", "src": "chuji"}, {"l": 448, "lt": "Lesson 148 Hurry Back 快点回来", "i": 1, "type": "dialog", "en": "Hey, Stan, can you do me a favor?", "zh": "嘿，斯坦，你可以帮我一个忙吗？", "audio": "chuji_l148_01.mp3", "localAudio": "audio_chunks/chuji_l148_01.mp3", "b64": "", "src": "chuji", "speaker": "Shella", "note": "说话人: Shella"}, {"l": 448, "lt": "Lesson 148 Hurry Back 快点回来", "i": 2, "type": "dialog", "en": "Sure. What is it?", "zh": "当然可以。什么忙？", "audio": "chuji_l148_02.mp3", "localAudio": "audio_chunks/chuji_l148_02.mp3", "b64": "", "src": "chuji", "speaker": "Stan", "note": "说话人: Stan"}, {"l": 448, "lt": "Lesson 148 Hurry Back 快点回来", "i": 3, "type": "dialog", "en": "Can you keep an eye on the kids while I go to the doctor's?", "zh": "你可以在我去看医生时帮我看一下小孩吗？", "audio": "chuji_l148_03.mp3", "localAudio": "audio_chunks/chuji_l148_03.mp3", "b64": "", "src": "chuji", "speaker": "Shella", "note": "说话人: Shella"}, {"l": 448, "lt": "Lesson 148 Hurry Back 快点回来", "i": 4, "type": "dialog", "en": "OK, but hurry back!", "zh": "好，但快一点回来！", "audio": "chuji_l148_04.mp3", "localAudio": "audio_chunks/chuji_l148_04.mp3", "b64": "", "src": "chuji", "speaker": "Stan", "note": "说话人: Stan"}];